#define Pi 3.1415926535897932384626433832795
#define Sm 0.0000000000000000000000000000000000001

//global variables
vec2 uv;
vec3 col;
float Wz = pow(10., 10.);

//auxiliary functions
float LineFunc(float x, vec2 a, vec2 b){
    return ((b.y-a.y)/(b.x-a.x))*(x-a.x)+a.y;
}
bool TriangleExists(vec2 a, vec2 b, vec2 c){
    vec2 m = (a+b+c)/3.;
    vec3 col1;
    if(LineFunc(uv.x, a, b) <= uv.y){
        col1 += vec3(1, 0, 0);
    }
    if(LineFunc(uv.x, a, c) <= uv.y){
        col1 += vec3(0, 1, 0);
    }
    if(LineFunc(uv.x, b, c) <= uv.y){
        col1 += vec3(0, 0, 1);
    }
    vec3 col2;
    if(LineFunc(m.x, a, b) <= m.y){
        col2 += vec3(1, 0, 0);
    }
    if(LineFunc(m.x, a, c) <= m.y){
        col2 += vec3(0, 1, 0);
    }
    if(LineFunc(m.x, b, c) <= m.y){
        col2 += vec3(0, 0, 1);
    }
    if(col1 == col2){
        return true;
    }
    return false;
}
float DistToLine(vec2 c, vec2 a, vec2 b){
    float f = (b.y-a.y)/(b.x-a.x+Sm)+Sm;
    float g = f + (1./f);
    float x = (c.y-a.y+(c.x/f)+(f*a.x))/g;
    float y = (a.x-c.x-(a.y/f)-(f*c.y))/(-g);
    vec2 H = vec2(x, y);
    return length(H-c);
}

vec3 Rotate(vec3 P, vec3 r){
    mat3 x, y, z;
    x = mat3(
        1, 0, 0,
        0, cos(r.x), -sin(r.x),
        0, sin(r.x), cos(r.x)
    );
    y = mat3(
        cos(r.y), 0, sin(r.y),
        0, 1, 0,
        -sin(r.y), 0, cos(r.y)
    );
    z = mat3(
        cos(r.z), -sin(r.z), 0,
        sin(r.z), cos(r.z), 0,
        0, 0, 1
    );
    return P*x*y*z;
}
vec3 GetNormal(vec3 A, vec3 B, vec3 C){
    vec3 Vab = B-A, Vac = C-A;
    vec3 M = (A+B+C)/3.;
    vec3 n = normalize(vec3(Vab.y*Vac.z-Vab.z*Vac.y, Vab.z*Vac.x-Vab.x*Vac.z, Vab.x*Vac.y-Vab.y*Vac.x));
    vec3 n1 = -n;
    if(length(M+n) > length(M+n1)){
        return n1;
    }
    return n;
}

//main functions
float TriangleZ(vec3 A, vec3 B, vec3 C){
    float z;
    vec2 a = A.xy/A.z, b = B.xy/B.z, c = C.xy/C.z;
    z = DistToLine(uv, b, c)/DistToLine(a, b, c)*A.z;
    z += DistToLine(uv, a, c)/DistToLine(b, a, c)*B.z;
    z += DistToLine(uv, b, a)/DistToLine(c, b, a)*C.z;
    return z;
}
void AddPolygon(vec3 A, vec3 B, vec3 C, vec3 t, vec3 O, vec3 r){
    vec3 A1 = A+t, B1 = B+t, C1 = C+t, O1 = O+t, r1 = r + 2.*Pi;
    A1 -= O1; B1 -= O1; C1 -= O1;

    A1 = Rotate(A1, r1); B1 = Rotate(B1, r1); C1 = Rotate(C1, r1);

    A1 += O1; B1 += O1; C1 += O1;

    vec2 a = A1.xy/A1.z, b = B1.xy/B1.z, c = C1.xy/C1.z;
    if(TriangleExists(a, b, c)){
        if(Wz > TriangleZ(A1, B1, C1)){
            Wz = TriangleZ(A1, B1, C1);
            col = -GetNormal(A1, B1, C1);
        }
    }
}
